from collections import defaultdict

def run_job(splits, mapper, reducer, R=3, combiner=None):
    """A tiny MapReduce runner (do not change it). Returns the sorted output."""
    buckets = []
    for split in splits:
        local = [defaultdict(list) for _ in range(R)]
        for k, v in split:
            for k2, v2 in mapper(k, v):
                local[sum(map(ord, str(k2))) % R][k2].append(v2)
        if combiner:
            local = [{k: [out for _, out in combiner(k, vs)] for k, vs in b.items()} for b in local]
        buckets.append(local)
    output = []
    for r in range(R):
        groups = defaultdict(list)
        for local in buckets:
            for k, vs in local[r].items():
                groups[k].extend(vs)
        for k in sorted(groups):
            output.extend(reducer(k, groups[k]))
    return sorted(output)

