splits = [
    [(1, ("Quito", 150)), (2, ("Quito", 170)), (3, ("Oslo", -40))],
    [(4, ("Quito", 100)), (5, ("Oslo", -20)), (6, ("Oslo", -30)), (7, ("Oslo", -10)), (8, ("Hanoi", 290))],
    [(9, ("Hanoi", 310))],
]
expected = {"Hanoi": 300.0, "Oslo": -25.0, "Quito": 140.0}
for comb in (None, combiner):
    got = dict(_run(splits, mapper, reducer, combiner=comb))
    assert set(got) == set(expected), got
    for k in expected:
        assert abs(got[k] - expected[k]) < 1e-9, (k, got[k], "with combiner" if comb else "without combiner")
# The combiner's output must have the same form as the mapper's, so it can be applied again.
once = list(combiner("Oslo", [v for _, v in mapper(0, ("Oslo", -40))]))
twice = list(combiner("Oslo", [v for _, v in once]))
assert once == twice

